import {offset,pad} from './time-utils.js';
import {featuredCityIds} from './featured-city-ids.js';
import {searchLocations,locations} from './locations.js';
export function installCityPicker(onChoose,getDate=()=>new Date()){
 const dialog=document.createElement('dialog');dialog.className='city-picker';dialog.innerHTML=`<form method="dialog"><div class="picker-heading"><div><p class="eyebrow">ANOTHER WINDOW, ANOTHER CITY</p><h2 id="picker-title">換一座城市</h2></div><button aria-label="關閉城市搜尋" class="picker-close">✕</button></div></form><label for="city-query">城市名稱、機場代號或 UTC 時差</label><input id="city-query" type="search" autocomplete="off" placeholder="台北、SFO、Hawaii、UTC+9…" aria-controls="city-results"><p id="city-search-status" role="status"></p><div id="city-results" class="city-results"></div><small>${featuredCityIds.length} 座城市提供專屬插畫與地標；其他城市使用通用光景。可輸入 UTC+9 等時差找城市。</small>`;dialog.setAttribute('aria-labelledby','picker-title');document.body.append(dialog);
 function utcLabel(date,zone){const value=offset(date,zone);return 'UTC'+(value<0?'−':'+')+pad(Math.floor(Math.abs(value)/60))+':'+pad(Math.abs(value)%60);}
 const input=dialog.querySelector('input'),results=dialog.querySelector('#city-results'),status=dialog.querySelector('[role=status]');let side='left',opener;
 function render(){const date=getDate(),found=searchLocations(input.value,input.value.trim()?30:featuredCityIds.length,date);status.textContent=found.length?`${input.value.trim()?'搜尋結果':'精選城市'} · ${found.length} 座 / ${Object.keys(locations).length} 座可搜尋`:'找不到城市，請試試英文名稱或機場代號。';results.replaceChildren(...found.map(c=>{const b=document.createElement('button');b.type='button';b.className='city-result';b.innerHTML=`<span><strong>${c.name}</strong> <span>${c.english}</span><small>${c.zone} · ${utcLabel(date,c.zone)} · ${c.featured?'專屬插畫與 3D':'通用光景'}</small></span><em>${c.codes.slice(0,3).join(' · ')}</em>`;b.addEventListener('click',()=>{onChoose(side,c.id);dialog.close();});return b;}));}
 input.addEventListener('input',render);dialog.addEventListener('keydown',e=>{const buttons=[...results.querySelectorAll('button')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const index=buttons.indexOf(document.activeElement),next=e.key==='ArrowDown'?index+1:index-1;if(next<0)input.focus();else buttons[Math.min(buttons.length-1,next)]?.focus();}else if(e.key==='Enter'&&document.activeElement===input){e.preventDefault();buttons[0]?.click();}if(e.key==='Escape')e.stopPropagation();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>opener?.focus());
 return {open(target){side=target;opener=document.activeElement;dialog.querySelector('h2').textContent=`更換${side==='left'?'左':'右'}側城市`;input.value='';render();dialog.showModal();input.focus();}};
}
